<script setup lang="ts">
import {ref} from 'vue'
import {useDb} from '../../../stores/db'
import {StatusBadge,KpiTile,PreviewBanner} from '../../../components/shared'
import {advanceAction} from '../../nexus/domain'
const db=useDb(),message=ref(''),evidence=ref(false)
function advance(state:'done_pending_verify'|'verified'){try{advanceAction('action-1',state,evidence.value?'evidence-1':undefined);message.value=`Action moved to ${state}.`}catch(e){message.value=e instanceof Error?e.message:''}}
</script>
<template><div class="page"><header class="page-header"><div><p class="eyebrow">Leadership control</p><h1>Control room</h1><p>Every headline drills to source, owner, freshness and next action.</p></div><PreviewBanner/></header><p v-if="message" class="card">{{message}}</p><div class="card-grid"><KpiTile label="Approved loans awaiting remittance" :value="1" to="/finance"/><KpiTile label="Unknown payment" value="Unknown" :unknown="1" to="/finance"/><KpiTile label="Stalled cases" :value="db.data.tasks.filter(t=>t.state==='blocked').length" to="/cs"/><KpiTile label="Recognised revenue" value="Unknown" :unknown="1" to="/finance"/></div><section class="card"><h2>Units and facts stay separate</h2><div class="actions"><StatusBadge label="Available units 23"/><StatusBadge label="PIVO holds 1"/><StatusBadge label="Developer-confirmed 2"/><StatusBadge label="Executed SPAs 0"/></div></section><section class="card"><h2>Action register</h2><article v-for="action in db.data.actionItems" :key="action.id"><div class="actions" style="justify-content:space-between"><span><strong>{{action.headline}}</strong><br>{{action.decision}}</span><StatusBadge :label="action.state"/></div><label><input v-model="evidence" type="checkbox"> Completion evidence attached</label><div class="actions"><el-button @click="advance('done_pending_verify')">Mark done pending verify</el-button><el-button @click="advance('verified')">Verify result</el-button></div><p class="source-meta">Expected effect remains a hypothesis until measured.</p></article></section></div></template>
